def gws_list(q: str) -> list:
    """Drive files matching a query, by gws (metadata only)."""
    params = {"q": q, "pageSize": 1000, "fields": "nextPageToken,files(id,name,size)"}
    p = subprocess.run([GWS, "drive", "files", "list", "--params", json.dumps(params)],
                       capture_output=True, text=True, encoding="utf-8", errors="replace")
    if p.returncode != 0:
        sys.exit(f"error: gws list failed: {(p.stderr or p.stdout).strip()[-300:]}")
    r = json.loads("\n".join(x for x in p.stdout.splitlines() if not x.startswith("Using keyring")))
    # shortcut: one page only, fine for the ~100-item import folder; add paging before listing anything bigger.
    if r.get("nextPageToken"):
        sys.exit("error: gws list returned more than one page; gws_list() does not page")
    return r.get("files", [])


def fetch_import_logs() -> None:
    """Download the June import logs (not its PDFs) from Drive into IMPORT by gws."""
    IMPORT.mkdir(parents=True, exist_ok=True)
    logs = [f for f in gws_list(f"'{IMPORT_FOLDER_ID}' in parents and trashed=false")
            if IMPORT_LOG.search(f["name"])]
    if not logs:
        sys.exit(f"error: no import logs found in Drive folder {IMPORT_FOLDER_ID}")
    got = 0
    for f in logs:
        out = IMPORT / f["name"]
        if out.exists() and out.stat().st_size == int(f.get("size") or -1):
            continue
        if not gws_get(f["id"], out):
            sys.exit(f"error: gws download failed: {f['name']} ({f['id']})")
        got += 1
    print(f"import logs: {len(logs)} in Drive, {got} downloaded to {IMPORT}")


